    point("g5s-poem-shanju", "poem", G5S, "默写王维《山居秋暝》", "空山新雨后，天气晚来秋。明月松间照，清泉石上流。竹喧归浣女，莲动下渔舟。随意春芳歇，王孙自可留。", B5S + "·第21课", "古诗;王维;必背"),
    point("g5s-poem-fengqiao", "poem", G5S, "默写张继《枫桥夜泊》", "月落乌啼霜满天，江枫渔火对愁眠。姑苏城外寒山寺，夜半钟声到客船。", B5S + "·第21课", "古诗;张继;必背"),
    point("g5s-poem-changxiangsi", "poem", G5S, "默写纳兰性德《长相思》", "山一程，水一程，身向榆关那畔行，夜深千帐灯。风一更，雪一更，聒碎乡心梦不成，故园无此声。", B5S + "·第21课", "词;纳兰性德;必背"),
    point("g5s-poem-yugezi", "poem", G5S, "默写张志和《渔歌子》", "西塞山前白鹭飞，桃花流水鳜鱼肥。青箬笠，绿蓑衣，斜风细雨不须归。", B5S + "·语文园地七", "词;张志和;必背"),
    point("g5s-poem-guanshu", "poem", G5S, "默写朱熹《观书有感》", "半亩方塘一鉴开，天光云影共徘徊。问渠那得清如许？为有源头活水来。", B5S + "·语文园地八", "古诗;朱熹;必背"),
    point("g5s-saying-bubao", "saying", G5S, "默写葛洪：不饱食以终日，……", "不饱食以终日，不弃功于寸阴。", B5S + "·语文园地二", "名句;惜时"),
    point("g5s-saying-shengnian", "saying", G5S, "默写陶渊明：盛年不重来，……", "盛年不重来，一日难再晨。及时当勉励，岁月不待人。", B5S + "·语文园地二", "名句;惜时"),
    point("g5s-saying-modeng", "saying", G5S, "默写岳飞：莫等闲，白了少年头，……", "莫等闲，白了少年头，空悲切。", B5S + "·语文园地二", "名句;惜时"),
