    point("g5x-saying-dushuyi", "saying", G5X, "俗语：读书须用意，……", "读书须用意，一字值千金。", B5X + "·语文园地六", "俗语"),
    point("g5x-saying-tingjun", "saying", G5X, "俗语：听君一席话，……", "听君一席话，胜读十年书。", B5X + "·语文园地六", "俗语"),
    point("g5x-saying-junziyu", "saying", G5X, "默写《论语》：君子喻于义，……", "君子喻于义，小人喻于利。", B5X + "·语文园地八", "名句;论语"),
    point("g5x-saying-tandang", "saying", G5X, "默写《论语》：君子坦荡荡，……", "君子坦荡荡，小人长戚戚。", B5X + "·语文园地八", "名句;论语"),
    point("g5x-saying-ceyin", "saying", G5X, "默写《孟子》：恻隐之心，……", "恻隐之心，仁之端也。", B5X + "·语文园地八", "名句;孟子"),
